arguments.command:
python -c "
import py_compile, sys, os

files = []
for root, dirs, fnames in os.walk('harness'):
    for f in fnames:
        if f.endswith('.py'):
            files.append(os.path.join(root, f))

errors = []
for f in sorted(files):
    try:
        py_compile.compile(f, doraise=True)
    except py_compile.PyCompileError as e:
        errors.append(str(e))

if errors:
    print('FAILURES:')
    for e in errors:
        print(e)
    sys.exit(1)
else:
    print(f'All {len(files)} Python files parse OK.')
"
